-- Modify "platform_mcp_connections" table
ALTER TABLE "platform_mcp_connections" ADD CONSTRAINT "platform_mcp_connections_reauthorization_state_check" CHECK (((reauthorization_required_at IS NULL) AND (reauthorization_reason IS NULL)) OR ((reauthorization_required_at IS NOT NULL) AND (reauthorization_reason IS NOT NULL) AND (reauthorization_reason = ANY (ARRAY['refresh_idle_expired'::text, 'authorization_expired'::text, 'refresh_reuse'::text, 'connection_revoked'::text, 'client_revoked'::text, 'authorization_lost'::text, 'security_reset'::text])))), ADD COLUMN "authorization_expires_at" timestamptz NULL, ADD COLUMN "reauthorization_required_at" timestamptz NULL, ADD COLUMN "reauthorization_reason" text NULL;
